import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import type { ReactNode } from "react";
import { getMyProfile } from "../api/people";

export interface RegisterPayload {
  role: "GUEST" | "ORGANIZER";
  email: string;
  password: string;
}

export interface RegisterResult {
  partyId: string;
  role: string;
}

interface AuthContextValue {
  token: string | null;
  username: string | null;
  displayName: string | null;
  permissions: string[];
  /** Set by `register()` for the lifetime of the current session — lets
   * `/onboarding` pick the right `Step[]` config right after a fresh
   * registration without a follow-up `GET /api/people/me` call. `null`
   * when the app was loaded from a stored token instead (returning user),
   * in which case callers fall back to a profile/leaderships lookup. */
  registeredRole: RegisterResult | null;
  login: (email: string, password: string) => Promise<void>;
  register: (payload: RegisterPayload) => Promise<RegisterResult>;
  /** Stores `jwt` under `"auth_token"`, decodes its claims, and updates
   * context state — identical body to the internal `applyToken`, just
   * exposed publicly for a non-login/register auth event (spec.md §4's
   * account-merge flow: the visitor is authenticated by a merge response,
   * not a `/api/auth/login` or `/api/auth/register` call). */
  applyExternalToken: (jwt: string) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextValue | null>(null);

function decodeJwtPayload(token: string): { sub?: string; permissions?: string[]; exp?: number } {
  try {
    const base64Url = token.split(".")[1];
    if (!base64Url) return {};
    const base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
    const json = atob(base64);
    return JSON.parse(json);
  } catch {
    return {};
  }
}

function isTokenExpired(token: string): boolean {
  const payload = decodeJwtPayload(token);
  if (!payload.exp) return true;
  return payload.exp * 1000 < Date.now();
}

function loadStoredAuth(): { token: string | null; username: string | null; permissions: string[] } {
  const stored = localStorage.getItem("auth_token");
  if (stored && !isTokenExpired(stored)) {
    const payload = decodeJwtPayload(stored);
    return { token: stored, username: payload.sub ?? null, permissions: payload.permissions ?? [] };
  }
  if (stored) {
    localStorage.removeItem("auth_token");
  }
  return { token: null, username: null, permissions: [] };
}

const NO_AUTH: ReturnType<typeof loadStoredAuth> = { token: null, username: null, permissions: [] };

export function AuthProvider({ children }: { children: ReactNode }) {
  // Read on first render, not at import: there is no localStorage while server rendering.
  const [initialAuth] = useState(() => (typeof window === "undefined" ? NO_AUTH : loadStoredAuth()));
  const [token, setToken] = useState<string | null>(initialAuth.token);
  const [username, setUsername] = useState<string | null>(initialAuth.username);
  const [permissions, setPermissions] = useState<string[]>(initialAuth.permissions);
  const [displayName, setDisplayName] = useState<string | null>(null);
  const [registeredRole, setRegisteredRole] = useState<RegisterResult | null>(null);

  const refreshDisplayName = useCallback(async () => {
    try {
      const me = await getMyProfile();
      setDisplayName(me.display_name);
    } catch {
      setDisplayName(null);
    }
  }, []);

  const applyToken = useCallback(
    (jwt: string) => {
      localStorage.setItem("auth_token", jwt);
      const payload = decodeJwtPayload(jwt);
      setToken(jwt);
      setUsername(payload.sub ?? null);
      setPermissions(payload.permissions ?? []);
      void refreshDisplayName();
    },
    [refreshDisplayName],
  );

  // Populate displayName on initial load when a valid token was already
  // stored (applyToken only runs on fresh login/register).
  useEffect(() => {
    if (initialAuth.token) {
      void refreshDisplayName();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const login = useCallback(
    async (email: string, password: string) => {
      const response = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      if (!response.ok) {
        const body = await response.json().catch(() => ({ message: "Login failed" }));
        throw new Error(body.message ?? "Login failed");
      }

      const { token: jwt } = await response.json();
      applyToken(jwt);
    },
    [applyToken],
  );

  const register = useCallback(
    async (payload: RegisterPayload): Promise<RegisterResult> => {
      const response = await fetch("/api/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          role: payload.role,
          email: payload.email,
          password: payload.password,
        }),
      });

      if (!response.ok) {
        const body = await response.json().catch(() => ({ message: "Registration failed" }));
        throw new Error(body.message ?? "Registration failed");
      }

      const { token: jwt, party_id: partyId, role } = await response.json();
      applyToken(jwt);
      const result = { partyId, role };
      setRegisteredRole(result);
      return result;
    },
    [applyToken],
  );

  const logout = useCallback(() => {
    localStorage.removeItem("auth_token");
    setToken(null);
    setUsername(null);
    setPermissions([]);
    setDisplayName(null);
    setRegisteredRole(null);
    window.location.href = "/login";
  }, []);

  const value = useMemo<AuthContextValue>(
    () => ({
      token,
      username,
      displayName,
      permissions,
      registeredRole,
      login,
      register,
      applyExternalToken: applyToken,
      logout,
    }),
    [token, username, displayName, permissions, registeredRole, login, register, applyToken, logout],
  );

  return <AuthContext value={value}>{children}</AuthContext>;
}

export function useAuth(): AuthContextValue {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

import {
  Package,
  LayoutList,
  Leaf,
  Plug,
  CalendarDays,
  UsersRound,
  Tag,
  Users,
  Warehouse,
  Image as ImageIcon,
  Images,
  ArrowLeftRight,
  Backpack,
  type LucideIcon,
} from "lucide-react";
import * as icons from "lucide-react";

export const ProductsIcon = Package;
export const PluginsIcon = Plug;
export const WarehouseIcon = Warehouse;
export const KragIcon = Users;
export const CategoriesIcon = Tag;
export const GroupsIcon = UsersRound;
export const TermsIcon = CalendarDays;
export const PhotosIcon = Images;
/** "Udostępnia" avatar-corner marker (Avatar's `showsSharesIcon`). */
export const SharesIcon = ArrowLeftRight;
/** "Przynosi" avatar-corner marker (Avatar's `showsBringsIcon`). */
export const BringsIcon = Backpack;

const ICON_MAP: Record<string, LucideIcon> = {
  package: Package,
  "layout-list": LayoutList,
  plug: Plug,
  warehouse: Warehouse,
  footprint: Leaf,
};

export function resolveIcon(name?: string): LucideIcon {
  if (!name) return Plug;

  if (ICON_MAP[name]) return ICON_MAP[name];

  // Convert kebab-case "arrow-right" to PascalCase "ArrowRight" for lucide lookup
  const pascalCase = name
    .split("-")
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join("");

  const icon = (icons as Record<string, unknown>)[pascalCase];
  if (typeof icon === "function") return icon as LucideIcon;

  return Plug;
}

export function PhotoPlaceholder({ size = 24 }: { size?: number }) {
  return <ImageIcon size={size} stroke="#94a3b8" strokeWidth={1.5} />;
}

import { useEffect, useState } from "react";
import type { Step, StepContext } from "../OnboardingWizard";
import { createMyCircle, type GroupResponse } from "../../../../api/groups";
import { createTerm } from "../../../../api/terms";
import { createMyOrganization } from "../../../../api/organizations";

const inputClass =
  "w-full rounded-xl border-[1.5px] border-line bg-cream px-3.5 py-2.5 text-sm text-ink outline-none focus:border-mint focus:ring-[3px] focus:ring-mint-soft";
const labelClass = "mb-1.5 block text-xs font-extrabold tracking-wide text-ink-soft";

/**
 * Holds the circle created by step 1 for step 2 to reference (`Grupa:
 * {step1 value}` in the mockup, and `circle_group_id` for `createTerm`).
 * Module-scoped rather than lifted into `OnboardingWizard`'s generic
 * `Step` contract — the wizard shell has no notion of cross-step state,
 * and only one onboarding flow is ever in progress per browser session.
 */
let createdCircle: GroupResponse | null = null;

/* ------------------------------------------------------------------ */
/*  Step 1/3 — Nazwa organizacji: mandatory (isSkippable: false, see     */
/*  export below) — every ORGANIZER account gets an Organization brand   */
/*  identity, per the "full pakiet" requirement. Throws (rather than      */
/*  silently no-op'ing like the skippable steps below) on an empty name  */
/*  so `OnboardingWizard.handleAdvance` blocks advancing instead of       */
/*  quietly skipping creation.                                           */
/* ------------------------------------------------------------------ */

function OrganizationNameStepBody({ ctx }: { ctx: StepContext }) {
  const [name, setName] = useState("");

  useEffect(() => {
    ctx.setSubmit(async () => {
      if (!name.trim()) throw new Error("Nazwa organizacji jest wymagana");
      await createMyOrganization({ name: name.trim() });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [name]);

  return (
    <div>
      <label htmlFor="onboarding-organization-name" className={labelClass}>
        Nazwa organizacji
      </label>
      <input
        id="onboarding-organization-name"
        className={inputClass}
        placeholder="np. Muzyczne Skrzaty"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
      <p className="mt-1.5 text-xs text-ink-soft">
        Własną stronę organizacji (z kolorami) skonfigurujesz później w menu.
      </p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Step 2/3 — Nazwa grupy: reuses createMyCircle()/handleAddGroup()'s   */
/*  logic (single text input + submit).                                 */
/* ------------------------------------------------------------------ */

function CircleNameStepBody({ ctx }: { ctx: StepContext }) {
  const [name, setName] = useState("");

  useEffect(() => {
    ctx.setSubmit(async () => {
      if (!name.trim()) return;
      createdCircle = await createMyCircle({ name: name.trim() });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [name]);

  return (
    <div>
      <label htmlFor="onboarding-circle-name" className={labelClass}>
        Nazwa grupy
      </label>
      <input
        id="onboarding-circle-name"
        className={inputClass}
        placeholder="np. Muzyczne Maluchy"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Step 3/3 — Termin zajęć: Grupa/Data/Opis only; needed items are    */
/*  added later from the panel's term modal.                            */
/* ------------------------------------------------------------------ */

function TermStepBody({ ctx }: { ctx: StepContext }) {
  const [occursOn, setOccursOn] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    ctx.setSubmit(async () => {
      if (!occursOn || !createdCircle) return;
      await createTerm({
        circle_group_id: createdCircle.id,
        occurs_on: occursOn,
        description: description || undefined,
      });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [occursOn, description]);

  return (
    <div className="flex flex-col gap-3">
      <div>
        <span className={labelClass}>Grupa</span>
        <p className="rounded-xl border-[1.5px] border-line bg-cream px-3.5 py-2.5 text-sm text-ink-soft">
          {createdCircle?.name ?? "—"}
        </p>
      </div>

      <div>
        <label htmlFor="onboarding-term-date" className={labelClass}>
          Data i godzina
        </label>
        <input
          id="onboarding-term-date"
          type="datetime-local"
          className={inputClass}
          value={occursOn}
          onChange={(e) => setOccursOn(e.target.value)}
        />
      </div>

      <div>
        <label htmlFor="onboarding-term-description" className={labelClass}>
          Opis (opcjonalnie)
        </label>
        <input
          id="onboarding-term-description"
          className={inputClass}
          placeholder="17:00 · Park Sołacki · wstęp wolny"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
      </div>
    </div>
  );
}

export const organizerSteps: Step[] = [
  {
    id: "organization-name",
    title: "Nazwa organizacji",
    isSkippable: false,
    render: (ctx) => <OrganizationNameStepBody ctx={ctx} />,
  },
  {
    id: "circle-name",
    title: "Nazwa grupy",
    isSkippable: true,
    render: (ctx) => <CircleNameStepBody ctx={ctx} />,
  },
  {
    id: "term",
    title: "Termin zajęć",
    isSkippable: true,
    render: (ctx) => <TermStepBody ctx={ctx} />,
  },
];

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import type { ReactNode } from "react";
import type { PluginResponse } from "../../api/plugins";
import { getPlugins } from "../../api/plugins";
import { createMessageHandler } from "./PluginMessageHandler";
import { MENU_MAIN, PRODUCT_DETAIL_INFO, PRODUCT_DETAIL_TABS, PRODUCT_LIST_FILTERS } from "../extensionPoints";
import { iframeRegistry } from "./iframeRegistry";
import type { ResolvedExtensionPoint } from "../resolveExtensionPoints";
import { resolveExtensionPoints } from "../resolveExtensionPoints";

interface PluginContextValue {
  plugins: PluginResponse[];
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
  getMenuItems: () => ResolvedExtensionPoint[];
  getProductDetailTabs: (pluginId?: string) => ResolvedExtensionPoint[];
  getProductListFilters: () => ResolvedExtensionPoint[];
  getProductDetailInfo: () => ResolvedExtensionPoint[];
}

const PluginContext = createContext<PluginContextValue | null>(null);

export function PluginProvider({ children }: { children: ReactNode }) {
  const [plugins, setPlugins] = useState<PluginResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refetch = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await getPlugins();
      setPlugins(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load plugins");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refetch();
  }, [refetch]);

  // Install the global postMessage handler once
  useEffect(() => {
    const handler = createMessageHandler(iframeRegistry);
    window.addEventListener("message", handler);
    return () => window.removeEventListener("message", handler);
  }, []);

  const getMenuItems = useCallback(
    () => resolveExtensionPoints(plugins, MENU_MAIN),
    [plugins],
  );

  const getProductDetailTabs = useCallback(
    (pluginId?: string) => resolveExtensionPoints(plugins, PRODUCT_DETAIL_TABS, pluginId),
    [plugins],
  );

  const getProductListFilters = useCallback(
    () => resolveExtensionPoints(plugins, PRODUCT_LIST_FILTERS),
    [plugins],
  );

  const getProductDetailInfo = useCallback(
    () => resolveExtensionPoints(plugins, PRODUCT_DETAIL_INFO),
    [plugins],
  );

  const value = useMemo<PluginContextValue>(
    () => ({ plugins, loading, error, refetch, getMenuItems, getProductDetailTabs, getProductListFilters, getProductDetailInfo }),
    [plugins, loading, error, refetch, getMenuItems, getProductDetailTabs, getProductListFilters, getProductDetailInfo],
  );

  return <PluginContext value={value}>{children}</PluginContext>;
}

export function usePluginContext(): PluginContextValue {
  const context = useContext(PluginContext);
  if (!context) {
    throw new Error("usePluginContext must be used within a PluginProvider");
  }
  return context;
}

import { useEffect, useRef } from "react";
import type { ExtensionPointType } from "../extensionPoints";
import { ADD_EVENT, MENU_MAIN, PRODUCT_DETAIL_INFO, PRODUCT_DETAIL_TABS, PRODUCT_LIST_FILTERS } from "../extensionPoints";
import { iframeRegistry } from "../host/iframeRegistry";

interface PluginFrameProps {
  pluginId: string;
  pluginName: string;
  pluginUrl: string;
  contextType: ExtensionPointType;
  contextData?: Record<string, unknown>;
  path: string;
  style?: React.CSSProperties;
  title?: string;
}

const CONTEXT_TYPE_PREFIX: Record<ExtensionPointType, string> = {
  [MENU_MAIN]: "RENDER",
  [PRODUCT_DETAIL_TABS]: "PRODUCT_DETAIL",
  [PRODUCT_LIST_FILTERS]: "FILTER",
  [PRODUCT_DETAIL_INFO]: "PRODUCT_DETAIL",
  [ADD_EVENT]: "RENDER",
};

function buildContextString(props: PluginFrameProps): string {
  const prefix = CONTEXT_TYPE_PREFIX[props.contextType] ?? "RENDER";
  const contextPayload: Record<string, unknown> = {
    pluginId: props.pluginId,
    pluginName: props.pluginName,
    hostOrigin: window.location.origin,
    ...props.contextData,
  };
  return `${prefix}${JSON.stringify(contextPayload)}`;
}

const SANDBOX = "allow-scripts allow-same-origin allow-forms allow-popups allow-modals allow-downloads";

export function PluginFrame(props: PluginFrameProps) {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const initializedRef = useRef(false);

  useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe) return;

    // Only set iframe src once to avoid reloading the plugin
    if (!initializedRef.current) {
      initializedRef.current = true;

      // Set name before src so the plugin can read context on load
      const contextString = buildContextString(props);
      iframe.name = contextString;

      // Also pass context as URL hash fragment (fallback for when window.name is cleared by dev servers)
      const src = new URL(props.path, props.pluginUrl);
      src.hash = encodeURIComponent(contextString);
      iframe.src = src.toString();
    }

    // Always register — must survive StrictMode's cleanup/re-run cycle
    iframeRegistry.register(iframe, {
      pluginId: props.pluginId,
      pluginUrl: props.pluginUrl,
    });

    return () => {
      iframeRegistry.unregister(iframe);
    };
  }, [props.pluginId, props.pluginName, props.pluginUrl, props.contextType, props.path, props.contextData]);

  return (
    <iframe
      ref={iframeRef}
      sandbox={SANDBOX}
      style={{ border: "none", width: "100%", height: "100%", ...props.style }}
      title={props.title ?? `Plugin: ${props.pluginName}`}
    />
  );
}

import { createBrowserRouter, Navigate, Outlet, useLocation, type RouteObject } from "react-router-dom";
import { AppShell } from "./components/layout/AppShell";
