      const windowName = 'PRODUCT_DETAIL{"pluginId":"warehouse","pluginName":"Warehouse","hostOrigin":"http://localhost:8080","productId":"prod-456"}';
      Object.defineProperty(window, "name", { value: windowName, writable: true });

